def top_two_majority(nums):
    first_index = 0
    second_index = 1
    first_count = 0
    second_count = 0

    for i in range(len(nums)):
        if nums[i] == nums[first_index]:
            first_count += 1
        elif nums[i] == nums[second_index]:
            second_count += 1
        elif first_count == 0:
            first_index = i
            first_count = 1
        elif second_count == 0:
            second_index = i
            second_count = 1
        else:
            first_count -= 1
            second_count -= 1

    first_majority = nums[first_index]
    second_majority = nums[second_index]

    first_count = 0
    second_count = 0

    for num in nums:
        if num == first_majority:
            first_count += 1
        elif num == second_majority:
            second_count += 1

    top_two = []
    if first_count > len(nums) // 3:
        top_two.append(first_majority)
    if second_count > len(nums) // 3:
        top_two.append(second_majority)

    return top_two
